import {questionExplorerMarkup} from './question-explorer.mjs?v=5';
import {workbookDimensions, workbookQuestions, workbookChoices, completeWorkbook, makeWorkbookReport} from './innerly-v1-model.mjs?v=mh-14';
import {workbookAreaGuidance} from './innerly-v1-guidance.mjs?v=report-5';

export const sampleProfiles = {
 everyday: {name:'Everyday mix', description:'Some things come naturally. Others deserve a little more space.', answers:[3,3,1,2,4,3, 3,3,3,4,3,3, 2,1,2,3,3,3, 4,1,3,3,1,3, 3,1,2,1,4,2, 3,4,3,3,3,4]},
 busy: {name:'A demanding week', description:'A busier inner world, with familiar strengths to lean on.', answers:[2,2,3,2,3,2, 4,2,3,3,4,2, 1,3,1,4,2,2, 3,3,4,2,2,3, 3,3,1,3,3,1, 2,4,2,4,2,3]},
 grounded: {name:'A steadier week', description:'More supportive responses, with room to keep learning.', answers:[4,3,1,3,4,3, 1,4,1,4,2,4, 3,1,3,1,4,3, 4,1,2,4,1,4, 4,1,3,1,4,3, 4,2,4,1,3,4]}
};
export const areaDesign = [
 {name:'Self-awareness', caption:'Understanding what is happening within.', color:'#6284d7', light:'#edf2fd', icon:'sun'},
 {name:'Thinking patterns', caption:'The stories your mind returns to.', color:'#9a7cd4', light:'#f3eefb', icon:'orbit'},
 {name:'Emotional balance', caption:'Making room between feeling and reacting.', color:'#4d9e9a', light:'#eaf6f3', icon:'wave'},
 {name:'Decision-making', caption:'Moving forward with intention.', color:'#cd9450', light:'#fcf3e5', icon:'branch'},
 {name:'Relationships', caption:'Connecting while staying true to yourself.', color:'#cd8298', light:'#fcf0f4', icon:'link'},
 {name:'Resilience & growth', caption:'Finding your footing when life shifts.', color:'#548fa7', light:'#eaf4f8', icon:'leaf'}
];
export const categories = {
 support:{name:'Strengths to lean on', short:'Strength', color:'#6b9e83', light:'#edf7ef'},
 focus:{name:'Room for improvement', short:'Growth opportunity', color:'#cb827d', light:'#fff0ed'},
 varies:{name:'Patterns to explore', short:'Sometimes', color:'#bfa24f', light:'#fff8df'}
};
const keys = Object.keys(categories);
export function reportAreas(language='en'){
 const hi=[['खुद की समझ','अपने भीतर के अनुभव को समझना।'],['सोच के तरीके','मन किन विचारों पर लौटता है।'],['भावनाओं का संतुलन','भावना और प्रतिक्रिया के बीच जगह बनाना।'],['निर्णय लेना','सोच-समझकर आगे बढ़ना।'],['रिश्ते','खुद को समझते हुए दूसरों से जुड़ना।'],['तनाव से उबरना और सीखना','बदलाव के बीच अपना रास्ता खोजना।']];
 return areaDesign.map((area,i)=>({...area,...(language==='hi'?{name:hi[i][0],caption:hi[i][1]}:{})}));
}
export function reportCategories(language='en'){
 const hi={support:['आपकी मददगार आदतें','मजबूती'],focus:['बेहतरी की गुंजाइश','काम करने का अवसर'],varies:['समझने योग्य पैटर्न','कभी-कभी']};
 return Object.fromEntries(keys.map(k=>[k,{...categories[k],...(language==='hi'?{name:hi[k][0],short:hi[k][1]}:{})}]));
}
export const escapeHTML = s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function reportSnapshot(answers,language='en'){
 if(!completeWorkbook(answers))throw new Error('The sample needs all 36 frequency responses.');
 const areas=workbookDimensions.map(d=>workbookAreaGuidance(answers,d.id,language));
 const items=areas.flatMap(a=>a.items);
 return {areas,items,counts:Object.fromEntries(keys.map(k=>[k,items.filter(i=>i.category===k).length]))};
}
export function icon(name){
 const paths={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',orbit:'<circle cx="12" cy="12" r="3"/><ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-35 12 12)"/><path d="M8 3c5-1 11 13 8 18"/>',wave:'<path d="M2 8c4-8 6 8 10 0s6 8 10 0M2 16c4-8 6 8 10 0s6 8 10 0"/>',branch:'<path d="M5 21v-7c0-4 12-4 12-8V2M5 3v3c0 4 12 4 12 8v7m-3-3 3 3 3-3M14 5l3-3 3 3"/>',link:'<path d="m9 15 6-6M8 17l-1 1a4.2 4.2 0 0 1-6-6l5-5a4.2 4.2 0 0 1 6 0m0 10a4.2 4.2 0 0 0 6 0l5-5a4.2 4.2 0 0 0-6-6l-1 1"/>',leaf:'<path d="M20 3C9 2 3 7 5 14c2 8 15 5 15-11ZM3 22 15 9"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z"/><path d="M17 11h1"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',check:'<path d="m5 12 4 4L19 6"/>'};
 return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.spark}</svg>`;
}
export function insightMarkup(area){
 const s=area.supports.find(item=>item.value>=3)||area.supports[0], f=area.focuses[0]||area.varies[0];
 return `<div class="insight support"><span>${icon('spark')} Strength to lean on</span><p>${s?escapeHTML(s.value<=1?`${s.response}: ${s.label.toLowerCase()}`:s.label):'Explore the responses that feel most supportive.'}</p></div><div class="insight ${f?.category||'varies'}"><span>${icon('branch')} ${area.focuses.length?'Room for improvement':'Worth exploring'}</span><p>${f?escapeHTML(f.label):'Keep noticing what helps in different situations.'}</p></div>`;
}
export function graphPath(area){return area.items.map((item,j)=>`${j?'L':'M'}${110+j*59},${166-item.value*34}`).join(' ');}
export function areaGraph(area,index,language='en'){
 const labels=reportCategories(language),design=reportAreas(language);
 return `<div class="response-chart-scroll" tabindex="0" role="region" aria-label="${escapeHTML(design[index].name)}"><svg class="response-chart" viewBox="0 0 450 202" aria-label="${escapeHTML(design[index].name)}: ${language==='hi'?'छह सवालों के जवाब। विवरण के लिए चुनें।':'six question responses. Select a bar or point for its exact question.'}">
 <g class="chart-grid">${workbookChoices(language).map((label,i)=>`<line x1="83" x2="429" y1="${166-i*34}" y2="${166-i*34}"/><text x="73" y="${170-i*34}" text-anchor="end">${label.split(' ').map((word,j)=>`<tspan x="73" dy="${j?13:0}">${escapeHTML(word)}</tspan>`).join('')}</text>`).join('')}</g>
 <path class="response-line" data-line="${index}" d="${graphPath(area)}"/>
 ${area.items.map((item,j)=>`<g class="chart-mark" data-question="${item.index}" role="button" tabindex="0" aria-label="${item.id}: ${escapeHTML(item.label)}. ${item.response}. ${labels[item.category].short}. ${language==='hi'?'सवाल देखें।':'View question.'}"><title>${escapeHTML(workbookQuestions[item.index].texts[language])} — ${item.response}</title><rect class="mark-target" x="${88+j*59}" y="15" width="44" height="184" fill="transparent"/><rect class="response-bar" data-bar="${item.index}" x="${98+j*59}" y="${166-item.value*34}" width="24" height="${Math.max(3,item.value*34)}" rx="7"/><circle class="response-point" data-point="${item.index}" cx="${110+j*59}" cy="${166-item.value*34}" r="5"/><text x="${110+j*59}" y="188" text-anchor="middle">${item.id}</text><circle data-status-dot="${item.index}" cx="${110+j*59}" cy="199" r="2.5" fill="${categories[item.category].color}"/></g>`).join('')}
 </svg></div>`;
}
export function questionReading(item){
 return `<span class="category-pill ${item.category}">${categories[item.category].short}</span><h3>${escapeHTML(item.label)}</h3><p class="reading-note">Based on “${escapeHTML(item.response)}” for this statement.</p><div class="reading-step"><span>ONE SMALL STEP</span><p>${escapeHTML(item.step)}</p></div><div class="reading-benefit"><span>WHAT THIS COULD HELP WITH</span><p>${escapeHTML(item.benefit)}</p></div>`;
}
export function planMarkup(snapshot){
 const choices=snapshot.areas.map(a=>a.next);
 return choices.map((item,i)=>`<article class="plan-item" style="--area:${areaDesign[i].color};--area-light:${areaDesign[i].light}"><div class="plan-icon">${icon(areaDesign[i].icon)}</div><div class="plan-copy"><span class="small-label">${escapeHTML(areaDesign[i].name)} · ${item.id}</span><h3>${escapeHTML(item.label)}</h3><p>${escapeHTML(item.step)}</p><div class="plan-benefit">${icon('arrow')}<span>${escapeHTML(item.benefit)}</span></div></div><label class="try-check"><input type="checkbox" data-tried="${item.id}"><span>${icon('check')}</span><b>Try this</b></label></article>`).join('');
}
export function responseTable(snapshot){return snapshot.items.map(i=>`<tr><td>${i.id}</td><td>${escapeHTML(workbookQuestions[i.index].texts.en)}</td><td>${i.response}</td><td>${categories[i.category].short}</td></tr>`).join('');}
export function focusItems(snapshot,category='support'){
 const items=snapshot.items.filter(i=>i.category===category);
 return items.length?items.map(i=>`<button data-question="${i.index}"><span>${i.id} · ${i.response}</span>${escapeHTML(i.label)} ${icon('arrow')}</button>`).join(''):'<p>No responses in this group for this sample. Try another profile.</p>';
}
export function conceptSampleReport(answers){return {...makeWorkbookReport(answers,{id:'innerly-concept-sample',createdAt:'2026-11-14T09:00:00Z',language:'en'}),illustrative:true};}
